<template><BioNexusDialog ref="dialog" size="standard" :title="mode==='create'?'Agregar examen al grupo':'Editar elemento'"><section class="form"><BioNexusFormField label="Id del examen" field-id="wi-exam" :error="examError" required><input id="wi-exam" ref="firstInput" v-model.number="draft.examId" class="bio-nexus-field" type="number" min="1"></BioNexusFormField><BioNexusFormField label="Descripcion" field-id="wi-description" :error="descriptionError" :help="draft.description.length+' de 60 caracteres'" required><input id="wi-description" v-model="draft.description" class="bio-nexus-field" maxlength="60"></BioNexusFormField><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div></section><template #footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close">Cancelar</button><button class="bio-nexus-action bio-nexus-action-primary" :class="{'save-disabled':submitDisabled&&mode==='edit'}" :disabled="submitDisabled&&mode==='edit'" @click="submit">{{saving?'Guardando...':mode==='create'?'Agregar':'Guardar'}}</button></template></BioNexusDialog></template><script setup>import{computed,nextTick,reactive,ref}from'vue';import BioNexusDialog from'@/components/ui/BioNexusDialog.vue';import BioNexusFormField from'@/components/ui/BioNexusFormField.vue';const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean,group:Object}),emit=defineEmits(['submit']),dialog=ref(null),firstInput=ref(null),mode=ref('create'),current=ref(null),attempted=ref(false),errorMessage=ref(''),original=ref(''),draft=reactive({examId:null,description:''});const values=computed(()=>({groupHtId:Number(props.group?.id),examId:Number(draft.examId),description:draft.description.trim()})),signature=computed(()=>JSON.stringify(values.value)),examError=computed(()=>attempted.value&&(!Number.isInteger(values.value.examId)||values.value.examId<=0)?'El examen es obligatorio.':''),descriptionError=computed(()=>attempted.value&&!values.value.description?'La descripcion es obligatoria.':''),submitDisabled=computed(()=>props.saving||(mode.value==='edit'&&(signature.value===original.value||!props.canUpdate)));async function show(){await dialog.value?.open();await nextTick();firstInput.value?.focus()}async function openCreate(){mode.value='create';current.value=null;draft.examId=null;draft.description='';original.value='';attempted.value=false;errorMessage.value='';await show()}async function openEdit(row){mode.value='edit';current.value=row;draft.examId=row?.examId||null;draft.description=row?.description||'';original.value=signature.value;attempted.value=false;errorMessage.value='';await show()}function submit(){attempted.value=true;if(examError.value||descriptionError.value||props.saving||(mode.value==='create'&&!props.canCreate)||submitDisabled.value)return;emit('submit',{mode:mode.value,record:current.value,values:values.value})}function close(){dialog.value?.close()}function setError(v){errorMessage.value=String(v||'')}function clearError(){errorMessage.value=''}defineExpose({openCreate,openEdit,close,setError,clearError})</script><style scoped>.form{display:grid;gap:var(--bio-nexus-space-3)}.save-disabled{opacity:.5;filter:grayscale(.35);cursor:not-allowed}</style>